def repl(s,old,new):
 p=rf'<figure[^>]*data-v188-plate="{re.escape(old)}"[\s\S]*?</figure>'; o,n=re.subn(p,new,s,count=1)
 if n!=1: raise SystemExit(f'{old}: expected 1, found {n}')
 return o

def main(root):
 ps=[Path(root)/'academic_payload/index.html',Path(root)/'app/src/main/assets/www/index.html']
 for p in ps:
  s=p.read_text(encoding='utf-8'); s=repl(s,'nereis-external',EXT); s=repl(s,'nereis-parapodium',PAR)
  # Insert new independent requirements after parapodium; protected digestive/circulatory/nervous remain byte-identical.
  anchor=PAR
  if anchor not in s: raise SystemExit('Nereis insertion anchor missing')
  s=s.replace(anchor,anchor+EXC+REP,1); p.write_text(s,encoding='utf-8')
 if ps[0].read_bytes()!=ps[1].read_bytes(): raise SystemExit('payload copies diverged')
 print('NEREIS-01/02 corrected; NEREIS-06/07 created; 03/04/05 untouched; BUILD_ELIGIBLE=NO')
if __name__=='__main__': main(sys.argv[1] if len(sys.argv)>1 else '.')